    slug: "agencies",
    title: "Agencies: How Marketing Agencies Use Lead Marketplaces for Clients",
    metaTitle: "Agencies Guide to Lead Marketplaces",
    excerpt: "How marketing and lead generation agencies use performance marketplaces to serve their clients.",
    metaDescription: "How marketing and lead generation agencies use performance marketplaces to source volume, manage client campaigns, and scale results across multiple verticals.",
